def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 120:
                rich_opp += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if isinstance(bid, (int, float)):
                prev_bids.append(float(bid))

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.25))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = supply <= 17
    ample = supply >= 22
    desperate_me = hp <= 3 or no_water >= 1
    stable_me = hp >= 7 and no_water == 0

    if desperate_me:
        if highest_prev > 0:
            bid = max(DAILY_SALARY * 0.95, highest_prev + 2.0)
        else:
            bid = DAILY_SALARY * 0.9
        return max(0.0, min(budget, bid))

    if ample and stable_me:
        bid = DAILY_SALARY * 0.22
        if urgent_opp >= 2:
            bid = DAILY_SALARY * 0.18
        return max(0.0, min(budget, bid))

    if scarcity:
        if highest_prev >= 110:
            bid = DAILY_SALARY * 0.28 if hp >= 6 else DAILY_SALARY * 0.88
        elif highest_prev >= 85:
            bid = min(highest_prev + 1.5, DAILY_SALARY * 0.92)
        else:
            bid = DAILY_SALARY * 0.62
        if rich_opp >= 2 and hp <= 5:
            bid = max(bid, DAILY_SALARY * 0.82)
        return max(0.0, min(budget, bid))

    if stable_me:
        if avg_prev >= 100:
            bid = DAILY_SALARY * 0.26
        elif avg_prev >= 80:
            bid = DAILY_SALARY * 0.42
        else:
            bid = DAILY_SALARY * 0.5
    else:
        if highest_prev >= 100:
            bid = DAILY_SALARY * 0.78
        elif highest_prev > 0:
            bid = max(DAILY_SALARY * 0.58, highest_prev * 0.72)
        else:
            bid = DAILY_SALARY * 0.55

    if budget < DAILY_SALARY * 2:
        bid = min(bid, budget * 0.55)

    return max(0.0, min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    EPISODE_DAYS = 10

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']
    current_day = day_context['day']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_budget, WATER_REQ * 10)

    yesterday_bids = []
    for opp in alive_opponents:
        prev_trace = opp.get('previous_trace', {})
        if prev_trace and prev_trace.get('bid') is not None:
            yesterday_bids.append(prev_trace['bid'])

    base_bid = DAILY_SALARY * 1.2

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= DAILY_SALARY * 1.4:
            base_bid = highest_prev_bid + 5
        elif highest_prev_bid >= DAILY_SALARY * 1.1:
            base_bid = highest_prev_bid + 1
        else:
            base_bid = DAILY_SALARY * 1.1

    if my_hp <= 2 or my_no_water_days >= 1:
        bid = max(base_bid, DAILY_SALARY * 1.5)
    elif my_hp <= 5:
        bid = max(base_bid, DAILY_SALARY * 1.35)
    else:
        bid = max(base_bid, DAILY_SALARY * 1.15)

    remaining_days = EPISODE_DAYS - current_day + 1
    if remaining_days <= 2 and my_budget > DAILY_SALARY * 2:
        bid = max(bid, DAILY_SALARY * 1.5)

    final_bid = min(my_budget, max(bid, WATER_REQ * 10))

    return final_bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25
    supply = int(day_context['supply'])  # ensure int
    day = int(day_context['day'])
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        # only us alive, just bid minimum
        return min(my_budget, DAILY_SALARY * 0.4)

    # Collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine base bid
    if yesterday_bids:
        max_yesterday = max(yesterday_bids)
    else:
        max_yesterday = 0.0

    # Estimate how many agents might compete
    num_alive = len(alive_opponents)
    total_required = (num_alive + 1) * WATER_REQ
    # If supply is abundant, we can bid lower
    if supply >= total_required:
        # enough water for everyone, bid just enough to secure water if needed
        if my_hp <= 2 and no_water_days > 0:
            target = DAILY_SALARY * 0.9
        else:
            target = DAILY_SALARY * 0.3
    else:
        # Water scarcity scenario
        if my_hp <= 2 or no_water_days >= 2:
            target = DAILY_SALARY * 0.95
        elif max_yesterday > 0:
            # Outbid yesterday's max by a small margin if we need water
            if my_hp <= 4:
                target = max_yesterday + 2.0
            else:
                target = max(DAILY_SALARY * 0.5, max_yesterday * 0.9)
        else:
            target = DAILY_SALARY * 0.5

    # Ensure we don't exceed budget
    bid = min(my_budget, target)
    # Guard against negative or very low bids
    bid = max(bid, 1.0)
    return bid

